import { Entity } from "../../Engine/Entity";
import type { BuildingConfigData } from "../Config/BuildingConfig";

export class BuildingEntity extends Entity {
    readonly kind = 'building';
    typeId = '';
    gridX = 0;
    gridY = 0;
    pendingIncome = 0;
    level = 1;

    // B 模块用，先初始化为 1
    synergyMultiplier = 1;

    /** 当前等级的产出速率（缓存，升级/相性变化时重算） */
    effectiveIncomePerSecond = 0;
    /** 当前等级的容量 */
    effectiveIncomeCap = 0;

    reset(): void {
        this.typeId = '';
        this.gridX = 0;
        this.gridY = 0;
        this.pendingIncome = 0;
        this.level = 1;
        this.synergyMultiplier = 1;
        this.effectiveIncomePerSecond = 0;
        this.effectiveIncomeCap = 0;
        this.x = 0;
        this.y = 0;
        this.alive = true;
    }

    /** 根据 config + level + synergy 重算产出参数 */
    recalc(config: BuildingConfigData): void {
        this.effectiveIncomePerSecond =
            config.incomePerSecond * config.incomeMultiplier(this.level) * this.synergyMultiplier;
        this.effectiveIncomeCap =
            config.incomeCap * config.capMultiplier(this.level);
    }
}